import{_ as a,o as e,c as n,a1 as l}from"./chunks/framework.Ccs17H5l.js";const d=JSON.parse('{"title":"Le format de couleur RGB 565","description":"","frontmatter":{},"headers":[],"relativePath":"reference/formats/rgb565.md","filePath":"reference/formats/rgb565.md"}'),o={name:"reference/formats/rgb565.md"};function p(r,s,t,c,i,u){return e(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="le-format-de-couleur-rgb-565" tabindex="-1">Le format de couleur RGB 565 <a class="header-anchor" href="#le-format-de-couleur-rgb-565" aria-label="Permalink to &quot;Le format de couleur RGB 565&quot;">​</a></h1><p>Le RGB 565 décrit une couleur sur 16 bits (2 octets). C&#39;est le format des pixels de l&#39;écran de la NumWorks, et donc celui des images <a href="./eif.html">EIF</a>.</p><h2 id="rgb-888-le-format-habituel" tabindex="-1">RGB 888 : le format habituel <a class="header-anchor" href="#rgb-888-le-format-habituel" aria-label="Permalink to &quot;RGB 888 : le format habituel&quot;">​</a></h2><p>Quand on écrit une couleur en RGB sans autre précision, c&#39;est du RGB 888 : trois nombres de 0 à 255, un pour le rouge, un pour le vert, un pour le bleu.</p><div class="language-css line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#D4D4D4;">rgb(255, 0, 0)     </span><span style="color:#6A9955;">/* rouge */</span></span>
<span class="line"><span style="color:#D4D4D4;">rgb(66, 138, 245)  </span><span style="color:#6A9955;">/* bleu clair */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Chaque nombre tient sur 8 bits, d&#39;où le nom « 888 ». Un pixel prend donc 3 octets, et on dispose de 16 777 216 couleurs.</p><h2 id="rgb-565-moins-de-bits-par-couleur" tabindex="-1">RGB 565 : moins de bits par couleur <a class="header-anchor" href="#rgb-565-moins-de-bits-par-couleur" aria-label="Permalink to &quot;RGB 565 : moins de bits par couleur&quot;">​</a></h2><p>Le RGB 565 garde les mêmes trois couleurs, mais avec moins de bits :</p><table tabindex="0"><thead><tr><th>Couleur</th><th>Bits</th><th>Valeurs possibles</th></tr></thead><tbody><tr><td>Rouge</td><td>5</td><td>0 à 31</td></tr><tr><td>Vert</td><td>6</td><td>0 à 63</td></tr><tr><td>Bleu</td><td>5</td><td>0 à 31</td></tr></tbody></table><p>Cela fait 16 bits, soit 2 octets par pixel, et 65 536 couleurs possibles.</p><p>Le vert a un bit de plus parce que l&#39;œil distingue mieux les nuances de vert que celles du rouge ou du bleu. Avec 16 bits, on les donne à la couleur qui compte le plus.</p><h2 id="pourquoi-ce-choix" tabindex="-1">Pourquoi ce choix <a class="header-anchor" href="#pourquoi-ce-choix" aria-label="Permalink to &quot;Pourquoi ce choix&quot;">​</a></h2><p>L&#39;écran fait 320 × 240 = 76 800 pixels.</p><table tabindex="0"><thead><tr><th>Format</th><th>Octets par pixel</th><th>Taille d&#39;une image plein écran</th></tr></thead><tbody><tr><td>RGB 888</td><td>3</td><td>230 400 octets (225 Kio)</td></tr><tr><td>RGB 565</td><td>2</td><td>153 600 octets (150 Kio)</td></tr></tbody></table><p>Une image plein écran pèse donc un tiers de moins. Sur une calculatrice dont la RAM fait environ 256 Kio, la différence compte. De plus, 2 octets tiennent exactement dans un entier <code>u16</code>, ce qui évite de découper des octets en morceaux.</p><h2 id="comment-un-pixel-est-range" tabindex="-1">Comment un pixel est rangé <a class="header-anchor" href="#comment-un-pixel-est-range" aria-label="Permalink to &quot;Comment un pixel est rangé&quot;">​</a></h2><p>Les 16 bits sont, de gauche à droite : 5 bits de rouge, 6 de vert, 5 de bleu.</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span>rouge  vert    bleu</span></span>
<span class="line"><span>01000  100010  11110</span></span>
<span class="line"><span>  8      34     30</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Ce pixel vaut <code>0b0100010001011110</code>, soit 17 502 en décimal (<code>0x445E</code> en hexadécimal).</p><h2 id="convertir-une-couleur" tabindex="-1">Convertir une couleur <a class="header-anchor" href="#convertir-une-couleur" aria-label="Permalink to &quot;Convertir une couleur&quot;">​</a></h2><h3 id="de-rgb-888-vers-rgb-565" tabindex="-1">De RGB 888 vers RGB 565 <a class="header-anchor" href="#de-rgb-888-vers-rgb-565" aria-label="Permalink to &quot;De RGB 888 vers RGB 565&quot;">​</a></h3><p>On garde seulement les bits de gauche de chaque couleur, ceux qui comptent le plus, et on jette les autres : 3 bits pour le rouge et le bleu, 2 bits pour le vert. C&#39;est ce que fait la conversion des images au moment de la compilation (<a href="https://github.com/Oignontom8283/eadkp/blob/dev/src/builder.rs" target="_blank" rel="noreferrer">builder.rs</a>).</p><div class="language-rust line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#569CD6;">fn</span><span style="color:#DCDCAA;"> rgb888_vers_rgb565</span><span style="color:#D4D4D4;">(</span><span style="color:#9CDCFE;">r</span><span style="color:#D4D4D4;">: </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">g</span><span style="color:#D4D4D4;">: </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">b</span><span style="color:#D4D4D4;">: </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">) -&gt; </span><span style="color:#4EC9B0;">u16</span><span style="color:#D4D4D4;"> {</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> r5</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">r</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) </span><span style="color:#569CD6;">as</span><span style="color:#4EC9B0;"> u16</span><span style="color:#D4D4D4;">;</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> g6</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">g</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">) </span><span style="color:#569CD6;">as</span><span style="color:#4EC9B0;"> u16</span><span style="color:#D4D4D4;">;</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> b5</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">b</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) </span><span style="color:#569CD6;">as</span><span style="color:#4EC9B0;"> u16</span><span style="color:#D4D4D4;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D4D4D4;">    (</span><span style="color:#9CDCFE;">r5</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">11</span><span style="color:#D4D4D4;">) | (</span><span style="color:#9CDCFE;">g6</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">5</span><span style="color:#D4D4D4;">) | </span><span style="color:#9CDCFE;">b5</span></span>
<span class="line"><span style="color:#D4D4D4;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">// rgb888_vers_rgb565(66, 138, 245) == 17 502</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="de-rgb-565-vers-rgb-888" tabindex="-1">De RGB 565 vers RGB 888 <a class="header-anchor" href="#de-rgb-565-vers-rgb-888" aria-label="Permalink to &quot;De RGB 565 vers RGB 888&quot;">​</a></h3><p>On étend chaque valeur à 8 bits. Pour que le maximum reste le maximum (31 doit redonner 255), on recopie les bits de gauche dans les places libres à droite.</p><div class="language-rust line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#569CD6;">fn</span><span style="color:#DCDCAA;"> rgb565_vers_rgb888</span><span style="color:#D4D4D4;">(</span><span style="color:#9CDCFE;">couleur</span><span style="color:#D4D4D4;">: </span><span style="color:#4EC9B0;">u16</span><span style="color:#D4D4D4;">) -&gt; (</span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">, </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">, </span><span style="color:#4EC9B0;">u8</span><span style="color:#D4D4D4;">) {</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> r5</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">couleur</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">11</span><span style="color:#D4D4D4;">) &amp; </span><span style="color:#B5CEA8;">0b11111</span><span style="color:#D4D4D4;">;</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> g6</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">couleur</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">5</span><span style="color:#D4D4D4;">) &amp; </span><span style="color:#B5CEA8;">0b111111</span><span style="color:#D4D4D4;">;</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> b5</span><span style="color:#D4D4D4;"> = </span><span style="color:#9CDCFE;">couleur</span><span style="color:#D4D4D4;"> &amp; </span><span style="color:#B5CEA8;">0b11111</span><span style="color:#D4D4D4;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> r8</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">r5</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) | (</span><span style="color:#9CDCFE;">r5</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">);</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> g8</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">g6</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">) | (</span><span style="color:#9CDCFE;">g6</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">4</span><span style="color:#D4D4D4;">);</span></span>
<span class="line"><span style="color:#569CD6;">    let</span><span style="color:#9CDCFE;"> b8</span><span style="color:#D4D4D4;"> = (</span><span style="color:#9CDCFE;">b5</span><span style="color:#D4D4D4;"> &lt;&lt; </span><span style="color:#B5CEA8;">3</span><span style="color:#D4D4D4;">) | (</span><span style="color:#9CDCFE;">b5</span><span style="color:#D4D4D4;"> &gt;&gt; </span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D4D4D4;">    (</span><span style="color:#9CDCFE;">r8</span><span style="color:#569CD6;"> as</span><span style="color:#4EC9B0;"> u8</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">g8</span><span style="color:#569CD6;"> as</span><span style="color:#4EC9B0;"> u8</span><span style="color:#D4D4D4;">, </span><span style="color:#9CDCFE;">b8</span><span style="color:#569CD6;"> as</span><span style="color:#4EC9B0;"> u8</span><span style="color:#D4D4D4;">)</span></span>
<span class="line"><span style="color:#D4D4D4;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">// rgb565_vers_rgb888(17 502) == (66, 138, 247)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>La couleur de départ était <code>(66, 138, 245)</code>. On retrouve <code>(66, 138, 247)</code> : l&#39;écart de 2 sur le bleu est la précision perdue en passant à 5 bits, et il ne se voit pas à l&#39;œil.</p><h2 id="pour-aller-plus-loin" tabindex="-1">Pour aller plus loin <a class="header-anchor" href="#pour-aller-plus-loin" aria-label="Permalink to &quot;Pour aller plus loin&quot;">​</a></h2><ul><li><a href="https://rgbcolorpicker.com/565" target="_blank" rel="noreferrer">Sélecteur de couleurs RGB 565</a> pour voir et choisir des couleurs dans ce format.</li><li><a href="./eif.html">Le format EIF</a>, qui range ces pixels dans un fichier d&#39;image.</li></ul>`,29)])])}const b=a(o,[["render",p]]);export{d as __pageData,b as default};
